def normalize_request(protocol, request_id, verified_identity, action, resource_id):
    if not verified_identity.subject or not verified_identity.tenant_id:
        raise ValueError('TRUSTED_CONTEXT_INCOMPLETE')
    if not isinstance(request_id, (str, int)) or isinstance(request_id, bool):
        raise ValueError('INVALID_REQUEST_ID')
    return {
        'protocol': protocol, 'request_id': request_id,
        'subject': verified_identity.subject, 'tenant_id': verified_identity.tenant_id,
        'scopes': verified_identity.scopes, 'action': action, 'resource_id': resource_id
    }
